function initGallery(t){if(t.dataset.attGalleryInit==="true")return;const a=t.querySelectorAll(".filters .chip");if(!a.length)return;t.dataset.attGalleryInit="true";const s=t.querySelectorAll(".gallery .gtile");a.forEach(l=>{l.addEventListener("click",()=>{a.forEach(e=>e.classList.remove("is-active")),l.classList.add("is-active");const r=l.dataset.filter;s.forEach(e=>{const i=r==="all"||e.dataset.cat===r;e.classList.toggle("is-hidden",!i)})})})}document.querySelectorAll("[data-att-gallery]").forEach(initGallery);
